CREATE TABLE "public"."installation" (
  "installation_id"              bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "installer_id"                 bigint,
  "installation_notes"           text,
  "wrap_date"                    date,
  "has_shipped"                  boolean                  NOT NULL DEFAULT false,
  "installation_date"            date,
  "installation_completed"       timestamp with time zone,
  "inspection_date"              date,
  "inspection_completed"         timestamp with time zone,
  "legacy_ref"                   text,
  "created_at"                   timestamp with time zone NOT NULL DEFAULT timezone('utc'::text, now()),
  "wrap_completed"               timestamp with time zone,
  "partially_shipped"            boolean                  DEFAULT false,
  "installation_report_received" timestamp with time zone,
  "in_warehouse"                 timestamp with time zone,
  "trade_30days"                 timestamp with time zone,
  "trade_6months"                timestamp with time zone,
  "site_changes"                 timestamp with time zone,
  "site_changes_detail"          text,
  "shipped_at"                   timestamp with time zone,
  "updated_at"                   timestamp with time zone NOT NULL DEFAULT now(),
  "cabfinaldate"                 date,
  "site_prep_install"            timestamp with time zone,
  CONSTRAINT "installation_pkey" PRIMARY KEY (installation_id),
  CONSTRAINT "fk_installer" FOREIGN KEY (installer_id) REFERENCES public.installers(installer_id) ON DELETE SET NULL
);

ALTER TABLE "public"."installation"
  ENABLE ROW LEVEL SECURITY;

CREATE TRIGGER on_has_shipped_change
  BEFORE UPDATE ON public.installation
  FOR EACH ROW
  WHEN ((old.has_shipped IS DISTINCT FROM new.has_shipped))
  EXECUTE FUNCTION public.update_shipped_at();

CREATE TRIGGER set_updated_at
  BEFORE UPDATE ON public.installation
  FOR EACH ROW
  EXECUTE FUNCTION public.handle_updated_at();

CREATE POLICY "Enable delete for admin only" ON "public"."installation"
  FOR DELETE
  TO PUBLIC
  USING ((public.clerk_user_role() = 'admin'::text));

CREATE POLICY "Enable insert for installation editors" ON "public"."installation"
  FOR INSERT
  TO PUBLIC
  WITH CHECK ((public.clerk_user_role() = ANY (ARRAY['admin'::text, 'installation'::text, 'service'::text, 'inspection'::text, 'plant'::text, 'scheduler'::text])));

CREATE POLICY "Enable read access for authenticated users" ON "public"."installation"
  FOR SELECT
  TO PUBLIC
  USING ((auth.role() = 'authenticated'::text));

CREATE POLICY "Enable update for installation editors" ON "public"."installation"
  FOR UPDATE
  TO PUBLIC
  USING ((public.clerk_user_role() = ANY (ARRAY['admin'::text, 'installation'::text, 'service'::text, 'inspection'::text, 'plant'::text, 'scheduler'::text])));

REVOKE ALL ON SEQUENCE "public"."installation_installation_id_seq" FROM "anon";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."installation_installation_id_seq" TO "anon";

REVOKE ALL ON SEQUENCE "public"."installation_installation_id_seq" FROM "authenticated";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."installation_installation_id_seq" TO "authenticated";

REVOKE ALL ON SEQUENCE "public"."installation_installation_id_seq" FROM "postgres";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."installation_installation_id_seq" TO "postgres";

REVOKE ALL ON SEQUENCE "public"."installation_installation_id_seq" FROM "service_role";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."installation_installation_id_seq" TO "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."installation" TO "anon", "authenticated";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."installation" TO "service_role";

REVOKE ALL ON TABLE "public"."installation" FROM "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."installation" TO "postgres";
